// The salt changed at run 66. A deployment must use the producer that generated
// its settlements, even while another deployment is active in the same site.
export function loadCrapsProducer(version) {
  if (version === 'craps-hot12-own30-longest-v5') return import('./craps-engine.js');
  if (version === 'craps-hot12-own30-longest-v4') return import('./schemas/5cd4b457/craps-engine.js');
  throw new Error(`Unsupported craps replay deployment engine version: ${version}`);
}
